/*
 * Register definitions for the Hi3798MV200 VDP display engine.
 *
 * Generated by gen-vdp200-regs.py from the mv100 driver's header: addresses come
 * from this chip's register map (verified against the offsets the SDK annotates
 * on every struct member), field bit positions are the mv100 driver's, verified
 * against the VDP v4 union definitions. Format codes, layer ids and strides are
 * carried over unchanged and are the driver's own encodings -- the ones the VDP v4
 * block has not been re-read for are marked below.
 *
 * Do not hand-edit: change the generator or the map instead.
 */

#ifndef _HI3798MV200_VDP_REGS_H_
#define _HI3798MV200_VDP_REGS_H_

#include <linux/bitops.h>
#define VO_CTRL		0x0000	/* SDK: VOCTRL */
#define   VO_CTRL_CK_GT_EN	BIT(31)
#define VO_MUX		0x0100
#define   VO_MUX_SDDATE_SEL	BIT(0)
#define   VO_MUX_HDDATE_SEL	BIT(1)
#define   VO_MUX_VGA_SEL	BIT(2)
#define   VO_MUX_HDMI_SEL	BIT(3)
#define   VO_MUX_DIGITAL	GENMASK(5, 4)
#define VO_INTSTA		0x0004	/* SDK: VOINTSTA */
#define VO_MSKINTSTA		0x0008	/* SDK: VOMSKINTSTA */
#define VO_INTMSK		0x000c	/* SDK: VOINTMSK */
/*
 * In spite of the name a set bit lets its source through: the vendor's enable
 * path ORs the bit in (VDP_DISP_SetIntMask, hal/98mv200/vdp_hal_chn.c:193) and
 * its disable path clears it (VDP_DISP_SetIntDisable, :217).  The boot value is
 * all ones, so every source starts enabled.
 */
#define VO_INT_DHD0_VTTHD1	BIT(0)
#define VO_INT_DHD0_VTTHD2	BIT(1)
#define VO_INT_DHD0_VTTHD3	BIT(2)
#define VO_INT_DHD1_VTTHD1	BIT(4)
#define VO_INT_DHD1_VTTHD2	BIT(5)
#define VO_INT_DHD1_VTTHD3	BIT(6)
#define VOAXICTRL		0x0030
#define VOAXICTRL1		0x0034
/*
 * Live reads off the system that displays (section 158b): both AXI words hold
 * 0x01110111 there, and the OEM kernel's own text contains no store to either
 * offset, so that is the reset state it runs with.  The earlier field decode
 * here (four-bit outstanding limits plus a multi-id bit) wrote 0x83ff instead,
 * which no displaying system has ever been observed to hold.
 */
#define VOAXICTRL_LIVE		0x01110111
#define VO_MASTER_RD_PRIO	0x8010
/* VDP_MASTER_SetRchnPrio's live value on the displaying system; 0 here. */
#define VO_MASTER_RD_PRIO_LIVE	4
/*
 * Graphics (RGB) path.  The mv200 header keeps this in one block at 0x7000; the
 * kernel running on this box splits it into a fetch unit, a layer stage, a
 * post/scale stage and mixer slots, and those addresses -- not the header's --
 * are what the picture and the channel depend on.  Every word below is a store
 * found in that kernel's own text and matched to a name in this SDK's
 * vdp_hal_gfx.c / vdp_software_selfdefine.c by its field position
 * (docs/mv200h-femac-reboot-2026-10-21.md sections 151b and 152a).
 *
 * Words whose meaning is not established are left out on purpose: this part's
 * channel block showed what writing an unverified offset does (nothing, and no
 * way to tell).
 */
/*
 * Write-back capture and the cycle buffer: the two blocks in this VDP that can
 * DMA *into* RAM.  Their place in this register file comes from the OEM
 * kernel's own stores, not from the mv200 C header: VDP_WBC_SetEnable/
 * SetAutoSt/SetOutIntf/SetUpdMode all store to base+0x6000 (wbc_en bit 31,
 * upd_mode bit 29, mode_out bits 23:22, vp_connection bits 25:24) with the
 * instance step at 0x400, VDP_WBC_SetRegUp stores to +0x6004, and the DMA side
 * is a separate block at base+0x9200 -- YaddrH/L +0x50/+0x54, CaddrH/L
 * +0x58/+0x5c, Ystride +0x60, Cstride +0x64, mmu bypass +0x14, low-delay lines
 * +0x20, width/height +0xb8, ctrl +0x00 (ckgt 14, chksum 11, flip 9, uv 8,
 * data_width 4), length/req_interval +0x04 (port ledger sections 164c and 165).
 * The header's WBC_DHD0_* at 0x9000 does not decode on this board at all.
 *
 * Two board-measured constraints on writing this family: the address words are
 * store-only (VDP_WBC_SetLayerAddr never reads them back), and a whole-word
 * store of all-ones is dropped outright -- only field-wise values are taken.
 * Both blocks are dumped rather than programmed here, so a boot can say what the
 * loader left.
 */
#define WBC0_CTRL		0x6000
#define WBC0_REGUP		0x6004
#define CYCBUF_GFX_BIND		0x8600
#define CYCBUF_MODE		0x8700

#define GFX0_BASE			0x8a00
#define   GFX0_STEP			0x200	/* per fetch unit (lsl #9) */
#define   GFX0_CTRL			(GFX0_BASE + 0x00)
#define     GFX0_CK_GT_EN		BIT(12)
#define     GFX0_ADDR_MAP_EN		BIT(13)
#define   GFX0_REQ_CTRL			(GFX0_BASE + 0x04)
#define   GFX0_REQ_EXT		(GFX0_BASE + 0x08)
/*
 * Live value of the fetch unit's third word on the system that displays
 * (section 158b): this driver never wrote the offset and reads back 0.
 * The fields are not decoded here, so the word is programmed verbatim.
 */
#define     GFX0_REQ_EXT_LIVE		0x703
#define     GFX0_CTRL_SEEN		BIT(0)	/* set on a displaying system */
#define     GFX0_REQ_CTRL_MASK		GENMASK(1, 0)
#define     GFX0_REQ_CTRL_INIT		2	/* VDP_GFX_SetReqCtrl(GFX0, 2) */
#define   GFX0_FMT			(GFX0_BASE + 0x40)
#define     GFX0_IFMT			GENMASK(7, 0)
#define     GFX0_BITEXT			GENMASK(9, 8)
#define   GFX0_IRESO			(GFX0_BASE + 0x44)
#define   GFX0_ORESO			(GFX0_BASE + 0x4c)
#define     GFX0_RESO_W			GENMASK(15, 0)
#define     GFX0_RESO_H			GENMASK(31, 16)
#define   GFX0_ADDR			(GFX0_BASE + 0x54)
#define   GFX0_STRIDE			(GFX0_BASE + 0x60)
#define     GFX0_LSTRIDE		GENMASK(15, 0)
#define     GFX0_CSTRIDE		GENMASK(31, 16)
/* the fetch unit also has +0x08, +0x40[19:16], +0x5c and +0x74 in use; the
 * vendor writes them too and their meaning has not been read yet.
 */
#define GFX0_IFMT_KRGB888		0x60	/* VDP v4 meaning not re-read yet */
#define GFX0_IFMT_ARGB8888		0x68	/* VDP v4 meaning not re-read yet */
#define GFX0_IFMT_RGBA8888		0xe8	/* VDP v4 meaning not re-read yet */
#define GFX0_BITEXT_3RD			3	/* VDP v4 meaning not re-read yet */

/*
 * Layer stage.  The stride here is 0x800 (lsl #11) while the fetch unit above
 * steps 0x200: the two families are indexed independently in the vendor's text,
 * so a layer number must not be shared between them without checking.
 */
#define L0_BASE				0x5000
#define   L0_STEP			0x800
#define   L0_CTRL			(L0_BASE + 0x00)
#define     L0_GALPHA			GENMASK(7, 0)
#define     L0_UPD_MODE			BIT(29)
#define     L0_NO_SEC			BIT(30)
#define     L0_EN			BIT(31)
#define   L0_REGUP			(L0_BASE + 0x04)	/* vendor stores 1 */
#define   L0_DISP_START			(L0_BASE + 0x80)
#define   L0_DISP_END			(L0_BASE + 0x84)
#define   L0_VIR_START			(L0_BASE + 0x88)
#define   L0_VIR_END			(L0_BASE + 0x8c)
#define     L0_POS_X			GENMASK(15, 0)
#define     L0_POS_Y			GENMASK(31, 16)

/*
 * Post/scale stage (GP): enable bit 31, upd_mode bit 29, and the stage order in
 * bits [22:21] and [24:23] (VDP_GP_SetIpOrder ORs 0x60000 into every write).  The
 * order values are now read off a working system: a displaying OEM's base+0x6800
 * is 0xe00000ff, whose bits [24:21] are 0, so the order fields stay 0.  The same
 * live read is what sets the enable/no-sec/upd_mode/galpha combination below, and
 * base+0x6804 reads 1 there, so this block's commit word is pulsed too.
 */
#define GP0_BASE			0x6800
#define   GP0_STEP			0x200
#define   GP0_CTRL			(GP0_BASE + 0x00)
#define     GP0_EN			BIT(31)
#define     GP0_NO_SEC			BIT(30)
#define     GP0_UPD_MODE		BIT(29)
#define     GP0_GALPHA			GENMASK(7, 0)
#define   GP0_REGUP			(GP0_BASE + 0x04)	/* live value: 1 */
#define   GP0_LIVE_CTRL			(GP0_EN | GP0_NO_SEC | GP0_UPD_MODE | \
					 FIELD_PREP(GP0_GALPHA, 0xff))
#define   GP0_IRESO			(GP0_BASE + 0x10)
#define   GP0_ORESO_W			0x6a00
#define   GP0_ORESO_H			0x6a10
#define     GP0_RESO			GENMASK(15, 0)

/*
 * Video processor 0, the stage the OEM lives between the graphics layer and the
 * interface.  Same control-word shape as GP0 but WITHOUT bit 30 (a displaying
 * OEM's base+0x4000 reads 0xa00000ff), and its commit word reads 0 there.
 */
#define VP0_BASE			0x4000
#define   VP0_CTRL			(VP0_BASE + 0x00)
#define   VP0_REGUP			(VP0_BASE + 0x04)
#define     VP0_EN			BIT(31)
#define     VP0_NO_SEC			BIT(30)
#define     VP0_UPD_MODE		BIT(29)
#define     VP0_GALPHA			GENMASK(7, 0)
#define   VP0_LIVE_CTRL			(VP0_EN | VP0_UPD_MODE | \
					 FIELD_PREP(VP0_GALPHA, 0xff))
/*
 * The commit word.  This block's configuration registers are shadowed: the
 * vendor's VDP_GFX_SetParaUpd(arg) (0xc06b5224) reads base+0xf00 and ORs
 * bit(17 + arg) back -- so the graphics surface's address/stride/format/geometry
 * only take effect after that pulse -- and VDP_GP_SetRegUp writes the same word,
 * which is why naming it after one block misleads.  VDP_DISP_SetParaUpd turned
 * out to be a trace stub in this build (it tail-calls a print helper), so only
 * the graphics bit matters for this driver.  Nothing here claimed a read-back
 * proves the latch: the word is dumped as `para` so a boot can say whether bit
 * 17 self-clears.
 */
#define PARA_UPD			0x0f00
#define   PARA_UPD_GFX(n)		BIT(17 + (n))

/*
 * Mixer slot words, read out of this part's own VDP_CBM_SetMixerPrio text
 * (/tmp/oem-vmlinux 0xc06b4a48, whose switch is on the header's VDP_CBM_MIX_E
 * ids -- vdp_ip_define.h:947-958, where MIX0 is commented "MIX0-DHD0" and the
 * vendor's live XDP_DRV_SetVidCBM passes MIX0 = 4):
 *
 *   MIXV0 (id 0, VP0's own mixer,   2 slots) slot 0x4108, bkg 0x4100
 *   MIXG0 (id 2, GP0's own mixer,   4 slots) slot 0x6908, bkg 0x6900, alpha 0x6904
 *   MIX0  (id 4, the HD channel's,  2 slots) slot 0x0208, bkg 0x0200
 *
 * Every surface block holds its mixer at +0x108 and its background at +0x100;
 * the channel's pair sits in the DISP block instead.  Slot layout is prio0
 * [3:0], prio1 [7:4], prio2 [11:8], prio3 [15:12], and the setter writes
 * layer_id + 1 for MIXV0/MIXG0 but the raw argument for MIX0 -- because MIX0's
 * ids are already biased.  VDP_PRIO_E (vdp_ip_define.h:996-1015) gives them:
 * for DHD0 without the VP/GP stages a graphics surface is 2, with them it is
 * GP0 = 2 and VP0 = 1; zero in a slot means no layer.
 *
 * The live words of a displaying OEM system (read on the board, ledger §156) are
 * the values written below, and they show the VP/GP stages in use: the channel
 * mixer at 0x0208 and GP0's mixer at 0x6908 both hold 0x00000021 -- slot 0 = 1
 * (VP0), slot 1 = 2 (GFX0/GP0) -- while VP0's own mixer at 0x4108 holds
 * 0x00000010.  The earlier reading of these slots as "GFX0 straight into the
 * channel, no GP setter" came from a BL scan, which cannot see the vendor's
 * indirect dispatch through its HAL function-pointer table; the live board beats
 * it.  Field meanings beyond the slot ids are still not established.
 *
 * The background word is the 10-bit triple Y[9:0] Cb[19:10] Cr[29:20], per the
 * bfi shifts in this part's VDP_CBM_SetMixerBkg (0xc06b48d8).  Left at its reset
 * 0 the uncovered area is YCbCr(0,0,0), which panels render as solid green, so a
 * green screen says no surface was admitted rather than that black was written.
 * A displaying OEM does not leave it at 0 and does not hold pure black either:
 * both background words (0x0200 and 0x4100) read 0x04080200, which decodes as
 * Y 512, Cb 32, Cr 1 -- not a black triple, so it is copied rather than explained.
 */
#define MIXV0_BKG			0x4100
#define MIXV0_SLOT			0x4108
#define MIXG0_BKG			0x6900
#define MIXG0_BKALPHA			0x6904
#define MIXG0_SLOT			0x6908
#define CBM0_BKG			0x0200
#define CBM0_SLOT			0x0208
#define   CBM_MIX_PRIO0			GENMASK(3, 0)
#define   CBM_MIX_PRIO1			GENMASK(7, 4)
#define   CBM_PRIO_VP0			0x1
#define   CBM_PRIO_GFX0			0x2
/* the seven mixer words as a displaying OEM system holds them live */
#define MIX_BKG_LIVE			0x04080200	/* 0x0200 and 0x4100 */
#define MIX_SLOT_LIVE			(FIELD_PREP(CBM_MIX_PRIO0, CBM_PRIO_VP0) | \
					 FIELD_PREP(CBM_MIX_PRIO1, CBM_PRIO_GFX0))
#define MIXV0_SLOT_LIVE			0x00000010	/* 0x4108 */
#define MIXG0_BKG_LIVE			0x00000000	/* 0x6900 */
#define MIXG0_BKALPHA_LIVE		0x00000000	/* 0x6904 */
/*
 * Where the HD channel lives on this part.  The vendor header for the chip
 * family puts DHD0 at VDP + 0xc000 with channels 0x400 apart
 * (common/drv/include/hi3798mv200/hi_reg_vdp.h:43648, inc/vdp_ip_define.h:100),
 * but that block is not what the system running on the box programs: read out of
 * its own kernel text, VDP_DHD_DEFAULT stores its 0x8011 seed at base+0xc200,
 * VDP_DISP_SetIntfEnable and VDP_DISP_OpenIntf compute
 * base + 0xc200 + (chn << 9), and their stores use 16-bit halves where that
 * header declares 12/10/10 fields (docs/mv200h-femac-reboot-2026-10-21.md
 * section 148).  The words at 0xc200 also read back what was written -- in the
 * OEM while it displays and in our own kernel after a bench write -- while
 * 0xc000 answers only four odd bit masks and holds 0 in a displaying system.
 *
 * Positions this part's channel block is documented to have but no store has
 * been seen at (clip pairs, csc, data_sel, sync_inv) are deliberately not
 * defined: writing an unverified offset into an unknown block is worse than not
 * writing it.
 */
#define DHD0_CTRL		0xc200
#define   DHD_CTRL_REGUP BIT(0)
#define   DHD_CTRL_DISP_MODE GENMASK(3, 1)
#define   DHD_CTRL_IOP BIT(4)
/*
 * VDP_DHD_Reset clears, besides intf_en/cbar_en/disp_mode, exactly two single
 * bits: 22 and 23.  The mv200 header clears gmm_en(13) and hdmi_mode(14) at the
 * same point in the sequence, so these are taken to be this part's positions for
 * that pair -- inferred from the reset mask, never read back.  The OEM leaves 23
 * raised while it displays.
 */
#define   DHD_CTRL_GMM_EN BIT(22)
#define   DHD_CTRL_HDMI_MODE BIT(23)
#define   DHD_CTRL_CBAR_SEL BIT(29)
#define   DHD_CTRL_CBAR_EN BIT(30)
#define   DHD_CTRL_INTF_EN BIT(31)
#define   DHD_CTRL_TWOCHN_DEBUG	BIT(15)
/*
 * The word the vendor puts in a channel before any timing exists
 * (VDP_DHD_DEFAULT, hal/98mv200/hal_specific/vdp_software_selfdefine.c:319,
 * stored straight at base+0xc200): regup, iop and twochn_debug with the
 * interface still disabled.
 */
#define DHD_CTRL_DEFAULT	(DHD_CTRL_REGUP | DHD_CTRL_IOP | DHD_CTRL_TWOCHN_DEBUG)
/*
 * Timing words, in the order the OEM's VDP_DISP_OpenIntf stores them and with
 * the field widths its bfi operations use.  The vertical counter is split over
 * two words here, unlike the single 12/10/10 word of the mv200 header.
 */
#define DHD0_VSYNC		0xc208
#define   DHD_VSYNC_VACT GENMASK(15, 0)
#define   DHD_VSYNC_VBB GENMASK(31, 16)
#define DHD0_VSYNC_VFB		0xc20c
#define   DHD_VSYNC_VFB GENMASK(15, 0)
#define DHD0_HSYNC1		0xc210
#define   DHD_HSYNC1_HACT GENMASK(15, 0)
#define   DHD_HSYNC1_HBB GENMASK(31, 16)
#define DHD0_HSYNC2		0xc214
#define   DHD_HSYNC2_HFB GENMASK(15, 0)
#define   DHD_HSYNC2_HMID GENMASK(31, 16)
#define DHD0_VPLUS		0xc218
#define   DHD_VPLUS_BVACT GENMASK(15, 0)
#define   DHD_VPLUS_BVBB GENMASK(31, 16)
#define DHD0_VPLUS_VFB		0xc21c
#define   DHD_VPLUS_BVFB GENMASK(15, 0)
#define DHD0_PWR		0xc220
#define   DHD_PWR_HPW GENMASK(15, 0)
#define   DHD_PWR_VPW GENMASK(23, 16)
/*
 * The two threshold words keep the mv200 field shape (thd[12:0], mode[15],
 * thd2[28:16], mode2[31]): that is exactly what the OEM's threshold helpers
 * store -- bfi #0,#13, bfi #16,#13, and single-bit modes at 15 and 31.  Which of
 * the pair is thd1/thd2 versus thd3/thd4 follows the header's order
 * (U_DHD0_VTTHD, U_DHD0_VTTHD3) and has not been told apart on the board.
 */
#define DHD0_VTTHD		0xc224
#define   DHD_VTTHD1 GENMASK(12, 0)
#define   DHD_VTTHD1_MODE BIT(15)
#define   DHD_VTTHD2 GENMASK(28, 16)
#define   DHD_VTTHD2_MODE BIT(31)
#define DHD0_VTTHD3		0xc228
#define   DHD_VTTHD3 GENMASK(12, 0)
#define   DHD_VTTHD3_MODE BIT(15)
#define   DHD_VTTHD4 GENMASK(28, 16)
#define   DHD_VTTHD4_MODE BIT(31)
/*
 * Which HD channel feeds the HDMI interface is not settled on this part, so the
 * driver asks one question -- HD_CHN -- and reaches every channel register
 * through it.  The v4 HAL maps HI_DRV_DISPLAY_0 to channel id 1
 * (msp/drv/vo/vdp_v4_0/hal/common/drv_disp_hal.c:280-291, whose caller at
 * drv_disp_hal.c:2460 notes "SDate attach to DHD1 all the time") and writes that
 * id straight into VO_MUX.hdmi_sel (hal/98mv200/vdp_hal_chn.c:1438).  The OEM
 * image actually running on this box disagrees: while it displays, VO_MUX is 0x1
 * -- hdmi_sel clear, so id 0 -- and the channel it programs is the one at
 * base+0xc200, i.e. id 0 (docs/mv200h-oem-oracle-2026-10-23.md and section 148
 * of the board ledger).  A board verdict that has not been retracted decides
 * HD_CHN; nothing else may name a channel.
 *
 * Channels are HD_CHN_OFFSET apart -- 0x200, the shift the OEM's OpenIntf
 * applies (lsl #9) -- and one channel's three threshold sources sit four bits
 * apart in VOINTMSK/VOINTSTA/VOMSKINTSTA (hi_reg_vdp.h: dhd0vtthd1-3 [2:0],
 * dhd1vtthd1-3 [6:4]).
 */
#define HD_CHN			0
#define HD_CHN_OFFSET		0x200

#define HD_CTRL			(DHD0_CTRL + HD_CHN * HD_CHN_OFFSET)
#define HD_VSYNC		(DHD0_VSYNC + HD_CHN * HD_CHN_OFFSET)
#define HD_VSYNC_VFB		(DHD0_VSYNC_VFB + HD_CHN * HD_CHN_OFFSET)
#define HD_HSYNC1		(DHD0_HSYNC1 + HD_CHN * HD_CHN_OFFSET)
#define HD_HSYNC2		(DHD0_HSYNC2 + HD_CHN * HD_CHN_OFFSET)
#define HD_VPLUS		(DHD0_VPLUS + HD_CHN * HD_CHN_OFFSET)
#define HD_VPLUS_VFB		(DHD0_VPLUS_VFB + HD_CHN * HD_CHN_OFFSET)
#define HD_PWR			(DHD0_PWR + HD_CHN * HD_CHN_OFFSET)
#define HD_VTTHD3		(DHD0_VTTHD3 + HD_CHN * HD_CHN_OFFSET)
#define HD_VTTHD		(DHD0_VTTHD + HD_CHN * HD_CHN_OFFSET)
#define HD_VBLANK_STATE		(DHD0_VBLANK_STATE + HD_CHN * HD_CHN_OFFSET)
/*
 * Not a configuration word: VDP_DISP_GetDHD0VblankState reads exactly this word
 * of the channel (base+0xc2a0), so it is the one place the channel says whether
 * it is counting.  A displaying OEM system holds 0x00f404d8 there while our
 * kernel holds 0x01000006 unchanged across seconds (docs/mv200h-femac-reboot-
 * 2026-10-21.md section 150a).
 */
#define DHD0_VBLANK_STATE	0xc2a0

/* hdmi_sel holds the id of the channel that reaches the interface, so both this
 * bit and the threshold source come out of HD_CHN and cannot disagree with it.
 */
/*
 * Which threshold source this driver treats as its vblank.  Not vtthd1: the
 * vendor's own config splits the three thresholds by purpose
 * (hal/common/drv_disp_hal.c:929-992) -- vtthd1 is the VIDEO layer's ISR point
 * (`thd = total * 50 / 100`), while vtthd2 is the GRAPHICS ISR point
 * (DISP_GFX_GetIsrPoint(), placed near the end of the frame so the update lands
 * before the next frame's back blanking).  A DRM CRTC flipped by the graphics
 * path therefore has vtthd2 as its frame event, and the board agrees: with
 * vtthd1 armed the channel asserted VOMSKINTSTA bit 1 -- dhd0vtthd2_int -- and
 * the driver logged it as "unexpected status 00000002" while
 * drm_crtc_handle_vblank() never ran and every commit ended in
 * "vblank wait timed out" (round of 2026-10-24, serial log).
 */
#define HD_INT_VBLANK		(HD_CHN ? VO_INT_DHD1_VTTHD2 : VO_INT_DHD0_VTTHD2)
#define HD_MUX_HDMI_SEL		(HD_CHN ? VO_MUX_HDMI_SEL : 0)
#define HDATE_VERSION		0xcc00
#define HDATE_STATE		0xcc10
#define HDATE_EN		0xcc04
#define HDATE_POLA_CTRL		0xcc08
#define HDATE_VIDEO_FORMAT		0xcc0c
#define HDATE_OUT_CTRL		0xcc14

#endif /* _HI3798MV200_VDP_REGS_H_ */
